    const zahl = arr[i];
    if (istPrimzahl(zahl)) {
      console.log(`Die Primzahl ist ${zahl}.`);
      return;
    }
  }

  // Helper-Funktion zum Prüfen, ob eine Zahl eine Primzahl ist
  function istPrimzahl(zahl) {
    if (zahl <= 1) {
      return false;
    }
    for (let I = 2; I <= Math.sqrt(zahl); i++) {
      if (zahl % I === 0) {
        return false;
      }
    }
    return true;
  }
}

// Beispielaufruf
const meineZahlen = [2, 17, 29, 31, 55];
pruefePrimzahl(meineZahlen);
```

